import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BB06nUeW.js";const p=JSON.parse('{"title":"Say It Out Loud: Spoken Interview Scripts","description":"","frontmatter":{},"headers":[],"relativePath":"14-say-it-out-loud.md","filePath":"14-say-it-out-loud.md"}'),r={name:"14-say-it-out-loud.md"};function i(s,e,l,c,d,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="say-it-out-loud-spoken-interview-scripts" tabindex="-1">Say It Out Loud: Spoken Interview Scripts <a class="header-anchor" href="#say-it-out-loud-spoken-interview-scripts" aria-label="Permalink to &quot;Say It Out Loud: Spoken Interview Scripts&quot;">​</a></h1><h2 id="project-pitch-60-seconds" tabindex="-1">Project Pitch (60 Seconds) <a class="header-anchor" href="#project-pitch-60-seconds" aria-label="Permalink to &quot;Project Pitch (60 Seconds)&quot;">​</a></h2><blockquote><p>&quot;I built AegisBank, an enterprise-grade digital banking and double-entry ledger platform built on the MERN stack with Express 5 and React 18. Unlike naive banking apps that simply increment or decrement balance columns, AegisBank enforces immutable double-entry bookkeeping where every transfer generates balanced debit and credit ledger entries inside atomic MongoDB sessions. It features anti-IDOR authorization guards, brute-force defenses, token blacklist logout, and instant CSV statement exports.&quot;</p></blockquote><h2 id="feature-scripts" tabindex="-1">Feature Scripts <a class="header-anchor" href="#feature-scripts" aria-label="Permalink to &quot;Feature Scripts&quot;">​</a></h2><h3 id="f1-double-entry-ledger-transfers" tabindex="-1">F1: Double-Entry Ledger Transfers <a class="header-anchor" href="#f1-double-entry-ledger-transfers" aria-label="Permalink to &quot;F1: Double-Entry Ledger Transfers&quot;">​</a></h3><blockquote><p>&quot;I built the Double-Entry Ledger transfer engine in <code>transaction.controller.js</code> to ensure financial integrity. Every transfer executes inside a MongoDB atomic session. The engine verifies that the authenticated user owns the source account, checks that the balance is sufficient, and writes a paired debit and credit record into <code>ledger.model.js</code>. Our schema strictly prohibits updates and deletes on ledger entries, guaranteeing an unalterable audit trail.&quot;</p></blockquote><h3 id="f2-token-blacklist-logout" tabindex="-1">F2: Token Blacklist &amp; Logout <a class="header-anchor" href="#f2-token-blacklist-logout" aria-label="Permalink to &quot;F2: Token Blacklist &amp; Logout&quot;">​</a></h3><blockquote><p>&quot;Because JWTs are stateless by design, logging out usually leaves tokens valid until expiration. In <code>auth.controller.js</code> and <code>blackList.model.js</code>, I implemented an active token blacklist. When a user logs out, their token is saved to MongoDB with a TTL index matching the token expiration time. Our auth middleware checks this blacklist before verifying signatures, instantly revoking compromised or logged-out sessions.&quot;</p></blockquote>',8)])])}const b=t(r,[["render",i]]);export{p as __pageData,b as default};
